VID.narration = {"look":{"bar":false},"scenes":[{"dur":7.616,"caps":[[0.5,6.11,"Lecture sixteen. Hardware software co-design: chips and code made for each other."]],"warp":[[0,0],[0.5,0.9],[7.616,4]]},{"dur":33.344,"caps":[[0.5,5.07,"Leafly: snap a leaf, get the plant's name."],[5.32,11.81,"Today the photo goes to the cloud. Answer: a few seconds."],[12.06,20.39,"AI pushes general hardware to its limits."],[20.64,26.01,"Moore's law is slowing: waiting won't do it."],[26.26,32.51,"A new chip is very expensive, so it needs large demand."]],"warp":[[0,0],[0.5,0.4],[5.32,2.8],[12.06,5.8],[20.64,8.8],[26.26,11.4],[33.344,14]]},{"dur":18.344,"caps":[[0.5,5.55,"Hardware designed around the software it will run."],[5.8,12.85,"Software tuned to make full use of that hardware."],[13.1,17.75,"Both shaped by each other: hardware–software co-design."]],"warp":[[0,0],[0.5,0.4],[5.8,3.6],[13.1,6.8],[18.344,11]]},{"dur":25.008,"caps":[[0.5,5.15,"AI models run on tensor operations."],[5.4,12.69,"Images: dense tensors. Recommendations: sparse ones."],[12.94,17.11,"AI usually runs in the cloud."],[17.36,23.45,"Personal models move it onto the phone: edge computing."]],"warp":[[0,0],[0.5,0.4],[5.4,3.2],[12.94,6],[17.36,9],[25.008,12.5]]},{"dur":20.201,"caps":[[0.5,6.67,"Cars: ADAS chips see the road and brake in milliseconds."],[6.92,12.61,"Data centres: DPUs and IPUs sit beside the CPU."],[12.86,18.79,"They take networking, storage and security off its hands."]],"warp":[[0,0],[0.5,0.4],[6.92,3.6],[12.86,7.6],[20.201,12]]},{"dur":28.119,"caps":[[0.5,7.39,"Bottom-up: hardware first, software later. Early GPU computing."],[7.64,14.21,"Top-down: the workload drives the chip. Volta tensor cores."],[14.46,20.39,"Co-design: both together. Snapdragon Ride Flex and Ride Vision."],[20.64,26.65,"Demand, software, hardware, round again: an iterative loop."]],"warp":[[0,0],[0.5,0.4],[7.64,3.8],[14.46,7.2],[20.64,10.6],[28.119,14]]},{"dur":33.344,"caps":[[0.5,5.95,"Six Leafly jobs. Which go into hardware?"],[6.2,11.41,"Heavy, stable jobs to hardware: speed and parallelism."],[11.66,18.31,"Rules that change stay in software, easy to update."],[18.56,24.73,"Simulate chip and code together before building anything."],[24.98,31.31,"High-level synthesis: describe the behaviour, get an HDL design."]],"warp":[[0,0],[0.5,0.4],[6.2,2.8],[11.66,5],[18.56,8],[24.98,11],[33.344,15]]},{"dur":31.765,"caps":[[0.5,7.39,"One photo on the phone's CPU: 132 ms."],[7.64,10.69,"The network takes 120 of them."],[10.94,16.71,"Network on the GPU: 40 ms, but 13 ms of it is copying."],[16.96,22.97,"A GPU twice as fast: only 32.5 ms."],[23.22,30.99,"A photo 4 times as big: copies take 52 ms."]],"warp":[[0,0],[0.5,0.4],[7.64,2.8],[10.94,5],[16.96,9],[23.22,11.4],[31.765,15]]},{"dur":21.571,"caps":[[0.5,8.03,"CPU: varied tasks. GPU: maths in parallel. Specialised: stable work."],[8.28,14.93,"CPU prepares, GPU runs the network, CPU shows the answer."],[15.18,20.55,"Framework, compiler, runtime: the stack maps the model to the chip."]],"warp":[[0,0],[0.5,0.4],[8.28,4.8],[15.18,8.4],[21.571,12.5]]},{"dur":23.731,"caps":[[0.5,5.15,"Measure latency, throughput, energy per result and cost."],[5.4,10.53,"Prototype, measure end to end, revisit the partition."],[10.78,15.19,"Speed one part up and the bottleneck moves."],[15.44,22.17,"Co-design trades power, performance, cost and time."]],"warp":[[0,0],[0.5,0.4],[5.4,3.6],[10.78,7],[15.44,9.8],[23.731,13]]},{"dur":16.672,"caps":[],"warp":[[0,0],[0.5,0.9],[5.24,2],[11.42,3.1],[16.672,9]]}]};
